var InvoiceReader=(()=>{
const root='/vendor/invoices/';let pdfPromise,scriptPromise;
function script(){return scriptPromise||=new Promise((resolve,reject)=>{const s=document.createElement('script');s.src=root+'tesseract.min.js';s.onload=resolve;s.onerror=()=>{scriptPromise=null;reject(Error('OCR-Bibliothek konnte nicht geladen werden.'))};document.head.append(s)})}
async function extract(file,progress=()=>{}){let worker,pdf;async function ocr(image){if(!worker){progress('Texterkennung wird vorbereitet …');await script();worker=await Tesseract.createWorker('deu+eng',1,{workerPath:root+'worker.min.js',corePath:location.origin+root+'core',langPath:location.origin+root+'lang',workerBlobURL:false,logger:m=>{if(m.status==='recognizing text')progress('Texterkennung: '+Math.round(m.progress*100)+' %')}})}return (await worker.recognize(image)).data.text}
try{if(file.type==='application/pdf'){pdfPromise||=import(root+'pdf.mjs').catch(e=>{pdfPromise=null;throw e});const lib=await pdfPromise;lib.GlobalWorkerOptions.workerSrc=root+'pdf.worker.mjs';pdf=await lib.getDocument({data:new Uint8Array(await file.arrayBuffer()),isEvalSupported:false,wasmUrl:root+'pdf-wasm/',useSystemFonts:true}).promise;if(pdf.numPages>20)throw Error('Bitte eine Rechnung mit höchstens 20 Seiten verwenden.');let texts=[];for(let n=1;n<=pdf.numPages;n++){progress('PDF-Seite '+n+' von '+pdf.numPages+' …');const page=await pdf.getPage(n),content=await page.getTextContent();let lines=[],line='',lastY=null;for(const item of content.items){if(typeof item.str!=='string')continue;const y=item.transform?.[5];if(lastY!==null&&Math.abs(y-lastY)>3&&line){lines.push(line);line=''}line+=item.str+' ';lastY=y;if(item.hasEOL){lines.push(line);line='';lastY=null}}if(line)lines.push(line);let text=lines.join('\n');if(text.replace(/\s/g,'').length<40){const initial=page.getViewport({scale:1}),view=page.getViewport({scale:Math.min(2,2200/Math.max(initial.width,initial.height))}),canvas=document.createElement('canvas');canvas.width=Math.ceil(view.width);canvas.height=Math.ceil(view.height);await page.render({canvasContext:canvas.getContext('2d'),viewport:view}).promise;text=await ocr(canvas);canvas.width=canvas.height=0}texts.push(text)}return texts.join('\n\n')}const bitmap=await createImageBitmap(file);try{if(bitmap.width*bitmap.height>60000000)throw Error('Das Bild ist zu groß. Bitte vor dem Hochladen verkleinern.');const scale=Math.min(1,2600/Math.max(bitmap.width,bitmap.height)),canvas=document.createElement('canvas');canvas.width=Math.ceil(bitmap.width*scale);canvas.height=Math.ceil(bitmap.height*scale);canvas.getContext('2d').drawImage(bitmap,0,0,canvas.width,canvas.height);const result=await ocr(canvas);canvas.width=canvas.height=0;return result}finally{bitmap.close()}}finally{if(worker)await worker.terminate();if(pdf)await pdf.destroy()}}
return {extract};})();
